#include <iostream>
#include <stdexcept>
void set_position(int& position, int target) {
    // Validate before changing the caller's integer.
    if (target < 0 || target > 10) {
        throw std::out_of_range("marker range");
    }
    position = target;
}
int main() {
    int position = 0;
    set_position(position, 3);
    std::cout << "first: " << position << '\n';
    set_position(position, 7);
    std::cout << "second: " << position << '\n';
}

#include <iostream>
int main() {
    int position = 0;
    // Wrong: both history records are captured before playback.
    const int before_first = position;
    const int before_second = position;
    position = 3;
    position = 7;
    position = before_second;
    std::cout << "wrong second undo: " << position << '\n';
    std::cout << "required second undo: 3\n";
    position = before_first;
    std::cout << "after both wrong undos: " << position << '\n';
}
